#[async_trait]
pub trait SpacesMcpServer: Send + Sync + 'static {
    async fn create_space(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn delete_space(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn get_space(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn list_spaces(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn unlock_space(&self, args: Value) -> std::result::Result<Value, McpError>;
}

pub struct SpacesMcpHandler<T: SpacesMcpServer> {
    inner: Arc<T>,
}

impl<T: SpacesMcpServer> Clone for SpacesMcpHandler<T> {
    fn clone(&self) -> Self {
        Self {
            inner: Arc::clone(&self.inner),
        }
    }
}

impl<T: SpacesMcpServer> SpacesMcpHandler<T> {
    pub fn new(svc: T) -> Self {
        Self {
            inner: Arc::new(svc),
        }
    }

    pub fn tools() -> Vec<Tool> {
        let app_uri = app_resource_uri("Spaces");
        vec![
            make_tool_with_app_meta(
                "spaces-create_space_v1",
                "Creates a space with a declared protection state. Protection is fixed at creation because it determines segment routing: an encrypted space writes into its own segments so unlocking decrypts a region rather than a row at a time. Changing it later is a rewrite, not a field update.",
                SPACES__CREATE_SPACE_SCHEMA_JSON,
                SPACES__CREATE_SPACE_OUTPUT_SCHEMA_JSON,
                Value::Null,
                "",
                Value::Null,
                &app_uri,
            ),
            make_tool_with_app_meta(
                "spaces-delete_space_v1",
                "Soft-deletes a space and every conversation within it.",
                SPACES__DELETE_SPACE_SCHEMA_JSON,
                SPACES__DELETE_SPACE_OUTPUT_SCHEMA_JSON,
                Value::Null,
                "",
                Value::Null,
                &app_uri,
            ),
            make_tool_with_app_meta(
                "spaces-get_space_v1",
                "Retrieves a single space.",
                SPACES__GET_SPACE_SCHEMA_JSON,
                SPACES__GET_SPACE_OUTPUT_SCHEMA_JSON,
                Value::Null,
                "",
                Value::Null,
                &app_uri,
            ),
            make_tool_with_app_meta(
                "spaces-list_spaces_v1",
                "Lists the spaces of an organization that the caller can see.",
                SPACES__LIST_SPACES_SCHEMA_JSON,
                SPACES__LIST_SPACES_OUTPUT_SCHEMA_JSON,
                Value::Null,
                "",
                Value::Null,
                &app_uri,
            ),
            make_tool_with_app_meta(
                "spaces-unlock_space_v1",
                "Unlocks a key-wrapped space for the duration of a session.",
                SPACES__UNLOCK_SPACE_SCHEMA_JSON,
                SPACES__UNLOCK_SPACE_OUTPUT_SCHEMA_JSON,
                Value::Null,
                "",
                Value::Null,
                &app_uri,
            ),
        ]
    }

    pub fn resources() -> Vec<Resource> {
        vec![
            serde_json::from_value(json!({
                "uri": app_resource_uri("Spaces"),
                "name": "telividb spaces",
                "mimeType": "text/html"
            }))
            .expect("generated app resource must be valid"),
        ]
    }

    pub fn resource_templates() -> Vec<ResourceTemplate> {
        vec![
            serde_json::from_value(json!({
                "uriTemplate": "space://organizations/{organization}/spaces/{space}", "name": "Space",
                "description": "Space resource (organizations/{organization}/spaces/{space})", "mimeType": "application/json"
            })).expect("generated resource template must be valid"),
        ]
    }
}

impl<T: SpacesMcpServer> ServerHandler for SpacesMcpHandler<T> {
    fn get_info(&self) -> ServerInfo {
        ServerInfo::new(
            ServerCapabilities::builder()
                .enable_tools()
                .enable_resources()
                .build(),
        )
        .with_server_info(Implementation::new("Spaces", "0.1.0"))
    }

    async fn list_tools(
        &self,
        _: Option<PaginatedRequestParams>,
        _: RequestContext<RoleServer>,
    ) -> std::result::Result<ListToolsResult, McpError> {
        Ok(ListToolsResult::with_all_items(Self::tools()))
    }
    async fn call_tool(
        &self,
        request: CallToolRequestParams,
        context: RequestContext<RoleServer>,
    ) -> std::result::Result<CallToolResponse, McpError> {
        let args = request
            .arguments
            .map_or_else(|| Value::Object(Default::default()), Value::Object);
        match request.name.as_ref() {
            "spaces-create_space_v1" => {
                let result = self.inner.create_space(args).await?;
                let text = serde_json::to_string(&result).map_err(|e| {
                    McpError::internal_error(format!("serialize response: {e}"), None)
                })?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            "spaces-delete_space_v1" => {
                if let Ok(schema) = ElicitationSchema::from_json_schema(
                    serde_json::from_value(json!({
                        "type": "object",
                        "properties": {
                        },
                        "required": []
                    }))
                    .unwrap(),
                ) {
                    let params = ElicitRequestParams::FormElicitationParams {
                        meta: None,
                        message:
                            "This tombstones the space and every conversation within it. Confirm?"
                                .to_string(),
                        requested_schema: schema,
                    };
                    match context.peer.create_elicitation(params).await {
                        Ok(result) if result.action != ElicitationAction::Accept => {
                            return Ok(CallToolResult::success(vec![ContentBlock::text(
                                "Action cancelled by user.",
                            )])
                            .into());
                        }
                        _ => {} // proceed (including errors — graceful degradation)
                    }
                }
                let result = self.inner.delete_space(args).await?;
                let text = serde_json::to_string(&result).map_err(|e| {
                    McpError::internal_error(format!("serialize response: {e}"), None)
                })?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            "spaces-get_space_v1" => {
                let result = self.inner.get_space(args).await?;
                let text = serde_json::to_string(&result).map_err(|e| {
                    McpError::internal_error(format!("serialize response: {e}"), None)
                })?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            "spaces-list_spaces_v1" => {
                let result = self.inner.list_spaces(args).await?;
                let text = serde_json::to_string(&result).map_err(|e| {
                    McpError::internal_error(format!("serialize response: {e}"), None)
                })?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            "spaces-unlock_space_v1" => {
                if let Ok(schema) = ElicitationSchema::from_json_schema(
                    serde_json::from_value(json!({
                        "type": "object",
                        "properties": {
                        },
                        "required": []
                    }))
                    .unwrap(),
                ) {
                    let params = ElicitRequestParams::FormElicitationParams {
                        meta: None,
                        message: "This unlocks a key-wrapped space for the session, making its contents readable. Confirm?".to_string(),
                        requested_schema: schema,
                    };
                    match context.peer.create_elicitation(params).await {
                        Ok(result) if result.action != ElicitationAction::Accept => {
                            return Ok(CallToolResult::success(vec![ContentBlock::text(
                                "Action cancelled by user.",
                            )])
                            .into());
                        }
                        _ => {} // proceed (including errors — graceful degradation)
                    }
                }
                let result = self.inner.unlock_space(args).await?;
                let text = serde_json::to_string(&result).map_err(|e| {
                    McpError::internal_error(format!("serialize response: {e}"), None)
                })?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            _ => Err(McpError::internal_error(
                format!("unknown tool: {}", request.name),
                None,
            )),
        }
    }

    async fn list_resources(
        &self,
        _: Option<PaginatedRequestParams>,
        _: RequestContext<RoleServer>,
    ) -> std::result::Result<ListResourcesResult, McpError> {
        Ok(ListResourcesResult::with_all_items(Self::resources()))
    }

    async fn list_resource_templates(
        &self,
        _: Option<PaginatedRequestParams>,
        _: RequestContext<RoleServer>,
    ) -> std::result::Result<ListResourceTemplatesResult, McpError> {
        Ok(ListResourceTemplatesResult::with_all_items(
            Self::resource_templates(),
        ))
    }

    async fn read_resource(
        &self,
        request: ReadResourceRequestParams,
        _: RequestContext<RoleServer>,
    ) -> std::result::Result<ReadResourceResponse, McpError> {
        let app_uri = app_resource_uri("Spaces");
        if request.uri == app_uri {
            let html = default_app_html(
                "telividb spaces",
                "0.1.0",
                "Named containers for related conversation, and where protection is declared.",
            );
            return Ok(ReadResourceResult::new(vec![
                ResourceContents::text(html, request.uri).with_mime_type("text/html"),
            ])
            .into());
        }
        Ok(ReadResourceResult::new(vec![ResourceContents::text("{}", request.uri)]).into())
    }
}

pub const SPACES_MCP_DEFAULT_BASE_PATH: &str = "/telividb/tenancy/v1/spaces/mcp";

pub struct SpacesMcpTransportConfig {
    pub transport: String,
    pub host: String,
    pub port: u16,
    pub base_path: String,
}

impl Default for SpacesMcpTransportConfig {
    fn default() -> Self {
        Self {
            transport: "streamable-http".into(),
            host: "0.0.0.0".into(),
            port: 8080,
            base_path: SPACES_MCP_DEFAULT_BASE_PATH.into(),
        }
    }
}

pub async fn serve_spaces_mcp_stdio<T: SpacesMcpServer>(
    svc: T,
) -> std::result::Result<(), Box<dyn std::error::Error>> {
    let handler = SpacesMcpHandler::new(svc);
    handler
        .serve(rmcp::transport::stdio())
        .await?
        .waiting()
        .await?;
    Ok(())
}

pub async fn serve_spaces_mcp<T: SpacesMcpServer>(
    svc: T,
    config: SpacesMcpTransportConfig,
) -> std::result::Result<(), Box<dyn std::error::Error>> {
    let handler = SpacesMcpHandler::new(svc);
    let transports: Vec<&str> = config
        .transport
        .split(',')
        .map(|s| s.trim())
        .filter(|s| !s.is_empty())
        .collect();
    let has_stdio = transports.iter().any(|t| *t == "stdio");
    let http_transport = transports
        .iter()
        .find(|t| **t == "sse" || **t == "streamable-http")
        .copied();

    if let Some(_ht) = http_transport {
        use rmcp::transport::streamable_http_server::{
            StreamableHttpServerConfig, StreamableHttpService, session::local::LocalSessionManager,
        };
        let h = handler.clone();
        let http_config = StreamableHttpServerConfig::default().with_sse_retry(None);
        let http_service = StreamableHttpService::new(
            move || Ok(h.clone()),
            Arc::new(LocalSessionManager::default()),
            http_config,
        );
        let app = axum::Router::new().nest_service(&config.base_path, http_service);
        let addr = format!("{}:{}", config.host, config.port);
        let listener = tokio::net::TcpListener::bind(&addr).await?;
        if has_stdio {
            tokio::spawn(async move {
                axum::serve(listener, app)
                    .await
                    .expect("HTTP server failed");
            });
        } else {
            axum::serve(listener, app).await?;
            return Ok(());
        }
    }

    if has_stdio {
        handler
            .serve(rmcp::transport::stdio())
            .await?
            .waiting()
            .await?;
    } else if http_transport.is_none() {
        return Err(format!("unsupported transport(s): {}", config.transport).into());
    }
    Ok(())
}
